INSERT INTO public.testimonials (id, agent_id, client_name, client_title, testimonial_text, rating, created_at, updated_at) VALUES
  ('f4a0311c-4558-45a7-b328-a5c0466e50bd', '976a874d-2c36-4799-b29e-db43604f01d8', 'M/M Shelton', 'Buyer', '“Working with Charles Jospeh was a game-changer. He knew the Seaport market intimately, found us a condo that matched our must-haves within a week, and negotiated a clean inspection credit that saved us thousands. Calm, strategic, and always reachable — highly recommend for anyone buying in the area.”', '5', '2025-11-12 00:30:12.882687+00', '2025-11-12 00:30:12.882687+00'),
  ('70159ec5-8f15-48ee-b601-370487ed8b42', '976a874d-2c36-4799-b29e-db43604f01d8', 'Charles Jacobs', 'Seller', '“Charles made selling our Seaport loft effortless. His marketing photos and targeted outreach brought multiple showings and a full-price offer in three days. He handled negotiations professionally and guided us through every step — great communication and excellent local expertise.”', '5', '2025-11-12 00:31:02.822613+00', '2025-11-12 00:31:02.822613+00'),
  ('f030494b-14c5-4499-b785-847c1a31fce1', '4ef7789b-20d8-40d3-9fee-3c41fae2bdc5', 'Kat S.', 'Buyer', 'Working with Betsy McCombs was an absolute pleasure. As first-time buyers in Boston, we had tons of questions — and Betsy guided us through every step with patience, honesty, and deep local knowledge. She found us the perfect condo in Charlestown, and even after closing, she checked in to make sure everything was going smoothly. We couldn’t have asked for a better experience!', '5', '2025-11-14 21:45:47.970795+00', '2025-11-14 21:45:47.970795+00'),
  ('fa6271e8-f6df-444f-944e-7e4d3c35809c', '4ef7789b-20d8-40d3-9fee-3c41fae2bdc5', 'M/M Trombley', 'Seller', 'Betsy’s marketing and negotiation skills were outstanding. She listed our Beacon Hill townhouse and had it under agreement within a week — and at a price well above what we expected. Her attention to detail, responsiveness, and understanding of the Boston market made the entire process seamless.', '5', '2025-11-14 21:46:42.183983+00', '2025-11-14 21:46:42.183983+00'),
  ('2225511f-cb90-4177-9281-0d25493856a2', '6c4f5998-c6eb-4c6b-94e0-fc4d45dccc90', 'Gary P.', 'Buyer', 'Maria (goes by Carmen) was incredible. This was not an easy process and we developed together a strategy to make a one-day offer that was compelling to the seller, preventing the home from being shown at an open house after our visit. After the P&S there were some property and permit issues and Carmen volunteered a long drive to the local town hall and proceeded to pull documents, evaluate and forward to our attorney. This was above and beyond the call of duty! Most important, Carmen truly cares about the client and it is obvious from the moment you meet her that your best interest is her best interest."-Gary P.', '5', '2025-11-15 01:35:03.679091+00', '2025-11-15 01:35:03.679091+00'),
  ('a0a49748-37bc-4c5b-b380-6ce0a1801882', 'ea18faa4-700f-4143-8c8e-436795a623af', 'mary smith', 'seller', 'this was the best experience ever', '5', '2026-02-04 03:17:57.505199+00', '2026-02-04 03:17:57.505199+00')
